import"./chunk-7CGTOI24.js";var a={slug:"fable-fevereiro-2027-ps5",title:"Fable tem data: 23 de fevereiro de 2027, inclusive no PS5",dek:"O RPG da Playground Games sai no mesmo dia para PC, Xbox Series X|S e PlayStation 5. Veja o que a data revela sobre a estrat\xE9gia do Xbox.",section:"games",kind:"noticia",tags:["Xbox","PlayStation","RPG","Lan\xE7amentos"],date:"2026-10-28",hero:{ref:"game:92550",pick:0,alt:"Arte de Fable com paisagem de conto de fadas"},body:[{p:"O novo *Fable* tem data de lan\xE7amento: **23 de fevereiro de 2027**. O RPG de a\xE7\xE3o em mundo aberto chega ao mesmo tempo para PC, Xbox Series X|S e PlayStation 5, segundo os registros do IGDB."},{p:"O desenvolvimento est\xE1 com a **Playground Games**, est\xFAdio brit\xE2nico conhecido pela s\xE9rie *Forza Horizon*, e a publica\xE7\xE3o \xE9 da Xbox Game Studios. A classifica\xE7\xE3o indicativa registrada \xE9 16 anos."},{ficha:"game:92550"},{h2:"Um RPG de escolhas e reputa\xE7\xE3o"},{p:"A descri\xE7\xE3o oficial resume a proposta: ser o her\xF3i que voc\xEA quiser, em um mundo aberto onde cada escolha molda a jornada, a reputa\xE7\xE3o \xE9 tudo e finais de conto de fadas n\xE3o s\xE3o garantidos. \xC9 exatamente o tom que fez a s\xE9rie querida, entre a fantasia brit\xE2nica e o humor \xE1cido."},{img:"game:92550",pick:2,caption:"Fable aposta em vilarejos, florestas e um humor bem brit\xE2nico. Imagem de divulga\xE7\xE3o."},{h2:"O detalhe que chama aten\xE7\xE3o: PS5 no primeiro dia"},{p:"Ver um jogo publicado pela Xbox Game Studios sair no PlayStation 5 no mesmo dia j\xE1 n\xE3o \xE9 novidade em 2026, mas ainda diz muito. A pr\xF3pria Playground mostra como essa estrat\xE9gia funciona na pr\xE1tica: *Forza Horizon 6* saiu primeiro no Xbox e no PC, e a vers\xE3o de PS5 est\xE1 marcada para 26 de janeiro de 2027."},{img:"game:348330",pick:0,caption:"Forza Horizon 6, outro jogo da Playground Games, chega ao PS5 em 26 de janeiro de 2027."},{p:"Com *Fable*, o caminho \xE9 mais direto: todas as plataformas juntas. Para quem joga no PlayStation, isso elimina a espera. Para o Xbox, a aposta \xE9 que o alcance maior compense a perda de exclusividade."},{h2:"O que esperamos"},{p:"Opini\xE3o da reda\xE7\xE3o: *Fable* tem a miss\xE3o de provar que a Playground sabe contar hist\xF3rias t\xE3o bem quanto constr\xF3i mundos. Os jogos de corrida do est\xFAdio j\xE1 mostraram que ele entende de paisagem e de ritmo. Falta mostrar que entende de gente."},{p:"Fevereiro de 2027 vai ser concorrido. Confira a [agenda de lan\xE7amentos at\xE9 mar\xE7o](/artigo/agenda-games-ate-marco-2027) para planejar a fila."}]};var o={source:"TMDB + IGDB",updatedAt:"2026-11-10",calendar:[],games:{92550:{id:92550,name:"Fable",type:"Jogo principal",cover:"cobc6d",shots:["scsoet","scsoeu","scsoew","scsoev","scsoez","scsoex"],arts:["ar2ziv","ar558t","ar558s"],genres:["RPG","Aventura","A\xE7\xE3o","Fantasia"],modes:["Single player"],devs:["Playground Games"],pubs:["Xbox Game Studios"],released:"2027-02-23",releases:{PC:"2027-02-23",PS5:"2027-02-23","Xbox Series X|S":"2027-02-23"},classInd:"16"},348330:{id:348330,name:"Forza Horizon 6",type:"Jogo principal",cover:"cobc5n",shots:["sc11fdi","sc11fdj","sc11fdk","sc11fdl","sc11fdp","sc11fdn"],arts:["ar5vr3","ar4amh"],genres:["Corrida","Simula\xE7\xE3o","Esporte","Arcade"],modes:["Single player","Multiplayer","Co-operative"],devs:["Playground Games"],pubs:["Xbox Game Studios"],released:"2026-05-19",releases:{"Xbox Series X|S":"2026-05-19",PC:"2026-05-19",PS5:"2027-01-26"},classInd:"L"}},movies:{},tv:{}};export{o as media,a as post};
